public interface MemberRepository extends JpaRepository<Member, Long> {

    @QueryHints(@QueryHint(name = "org.hibernate.readOnly", value = "true"))
    Optional<Member> findReadOnlyById(Long id);
}

@Test
@Transactional
void 힌트() {
    em.clear();
    Member m = memberRepository.findReadOnlyById(1L).orElseThrow();

    SessionImpl session = em.unwrap(SessionImpl.class);
    EntityEntry entry = session.getPersistenceContext().getEntry(m);
    System.out.println("상태:   " + entry.getStatus());
    System.out.println("스냅샷: " +
            Arrays.toString(entry.getLoadedState()));
}

