-- 고쳐도 안 나간다

@Test
@Transactional
void 고쳐도() {
    em.clear();
    Member m = memberRepository.findReadOnlyById(1L).orElseThrow();
    m.setUsername("고쳤다");
    em.flush();
    System.out.println("flush 했는데 update 가 없다");

    em.clear();
    System.out.println("다시 읽으면: " +
            memberRepository.findById(1L).orElseThrow().getUsername());
}

