@Test
@Transactional
void 같은_행() {
    em.clear();
    Member first = memberRepository.findReadOnlyById(1L).orElseThrow();
    Member second = memberRepository.findById(1L).orElseThrow();

    System.out.println("같은 객체? " + (first == second));
    second.setUsername("고침");
    em.flush();
    System.out.println("flush 끝");
}

