-- 메모리를 잰다

@Test
@Transactional
void 메모리() {
    for (boolean ro : new boolean[]{false, true}) {
        em.clear();
        System.gc();
        long before = used();
        if (ro) memberRepository.findAllReadOnly();
        else    memberRepository.findAll();
        long after = used();
        System.out.printf("readOnly=%-5s %d KB%n", ro,
                (after - before) / 1024);
    }
}

