-- flush 시간도 준다

@Test
@Transactional
void flush_시간() {
    for (boolean ro : new boolean[]{false, true}) {
        em.clear();
        if (ro) memberRepository.findAllReadOnly();
        else    memberRepository.findAll();

        long t = System.nanoTime();
        em.flush();
        System.out.printf("readOnly=%-5s flush %d ms%n", ro,
                (System.nanoTime() - t) / 1_000_000);
    }
}

