-- DTO 로 읽으면 애초에 없다

@Query("select new study.datajpa.dto.MemberDto(m.id, m.username, t.name)"
     + " from Member m left join m.team t")
List<MemberDto> findDtos();

@Test
@Transactional
void DTO() {
    em.clear();
    System.gc();
    long before = used();
    List<MemberDto> dtos = memberRepository.findDtos();
    System.out.printf("DTO %d KB, %d건%n",
            (used() - before) / 1024, dtos.size());

    SessionImpl s = em.unwrap(SessionImpl.class);
    System.out.println("컨텍스트 엔티티 수: " +
            s.getPersistenceContext().getNumberOfManagedEntities());
}

